{"function": "() => {
    // Extract just the poem text from the specific article section
    // The poem appears to be in article[ref="e72"]
    const poemArticle = document.querySelector('article[ref="e72"]');
    if (!poemArticle) return "Poem article not found";

    // Get all direct children that are likely poem lines
    const children = poemArticle.querySelectorAll('div[ref]');
    let poemLines = [];

    for (let child of children) {
        const text = child.textContent.trim();
        if (text) {
            poemLines.push(text);
        }
    }

    // If we found lines, join them with line breaks
    if (poemLines.length > 0) {
        return poemLines.join('\n');
    }

    // If not, try to get the text content and clean it up
    const rawText = poemArticle.textContent;

    // Split by newlines and clean up
    const lines = rawText.split('\n').map(line => line.trim()).filter(line => line.length > 0);

    // Filter out lines that are clearly not part of the poem
    const poemStart = lines.findIndex(line => line.includes("I have not ever seen my father"));
    if (poemStart === -1) return rawText;

    const poemEnd = lines.findIndex((line, i) => i > poemStart && line.includes("Copyright Credit"));
    if (poemEnd === -1) return lines.slice(poemStart).join('\n');

    return lines.slice(poemStart, poemEnd).join('\n');
}"}

