  // Get all text content from the main article
  const article = document.querySelector('article');
  if (!article) return 'Article not found';

  const fullText = article.innerText || article.textContent;

  // Try to extract just the poem part
  const lines = fullText.split('\n').map(line => line.trim()).filter(line => line.length > 0);

  // Find start and end of poem
  let poemStart = -1;
  let poemEnd = -1;

  for (let i = 0; i < lines.length; i++) {
    if (lines[i].includes('I have not ever seen my father')) {
      poemStart = i;
    }
    if (poemStart !== -1 && lines[i].includes('Copyright Credit:')) {
      poemEnd = i;
      break;
    }
  }

  if (poemStart === -1) return fullText; // Return everything if can't find boundaries

  const poemLines = lines.slice(poemStart, poemEnd === -1 ? lines.length : poemEnd);

  // Reconstruct with original spacing (checking for empty lines)
  const originalLines = fullText.split('\n');
  const reconstructed = [];
  let inPoem = false;

  for (let i = 0; i < originalLines.length; i++) {
    const line = originalLines[i];
    if (line.includes('I have not ever seen my father')) {
      inPoem = true;
    }
    if (inPoem && line.includes('Copyright Credit:')) {
      break;
    }
    if (inPoem) {
      reconstructed.push(line);
    }
  }

  return reconstructed.join('\n').trim();
}"}

{"function": "() => {
  // Find the article containing the poem
  const article = document.querySelector('article');
  if (!article) return null;

  // Look for the poem text - it's in generic elements with text content
  // Try to find the main poem container
  const poemContainer = article.querySelector('[ref="e76"]') || 
                       article.querySelector('div[class*="poem"]') ||
                       article.querySelector('div[class*="text"]');

  if (poemContainer) {
    return poemContainer.innerText;
  }

  // Alternatively, collect all text nodes in the article, excluding copyright
  const walker = document.createTreeWalker(
    article,
    NodeFilter.SHOW_TEXT,
    null,
    false
  );

  let text = '';
  let node;
  while (node = walker.nextNode()) {
    text += node.textContent + '\n';
  }

  // Clean up
  text = text.replace(/\n\s*\n/g, '\n\n').trim();

  // Try to extract just the poem (before "Copyright Credit:")
  const copyrightIndex = text.indexOf('Copyright Credit:');
  if (copyrightIndex !== -1) {
    text = text.substring(0, copyrightIndex).trim();
  }

  return text;
}"}

